var RECIPE_COOKING_DATA = {
"Classic Oatmeal with Berries":{prepTime:"5 mins",cookTime:"10 mins",steps:["Bring milk to a gentle simmer in a saucepan over medium heat.","Add rolled oats and stir, cooking for 5-7 minutes until creamy.","Slice the banana into rounds.","Transfer oatmeal to a bowl, top with blueberries and banana slices.","Top with granola and strawberries. Drizzle with honey and maple syrup."]},
"Scrambled Eggs & Toast":{prepTime:"5 mins",cookTime:"8 mins",steps:["Crack eggs into a bowl, add a splash of whole milk, and whisk until smooth.","Toast the whole wheat bread slices.","Melt butter in a non-stick pan over medium-low heat.","Pour in eggs and stir gently with a spatula, forming soft curds.","When eggs are nearly set, remove from heat and stir in cheddar cheese.","Serve eggs alongside toast."]},
"Greek Yogurt Parfait":{prepTime:"5 mins",cookTime:"0 mins",steps:["Wash and slice the strawberries. Slice the banana into rounds.","Layer half the greek yogurt in a bowl or glass.","Add a layer of granola, rolled oats, half the strawberries, and blueberries.","Add remaining yogurt, top with remaining granola, strawberries, and banana slices.","Drizzle with honey and serve immediately."]},
"Avocado Toast with Egg":{prepTime:"5 mins",cookTime:"8 mins",steps:["Toast the whole wheat bread slices until golden.","Fry or poach the eggs to your preference.","Mash the avocado with a fork and season with salt, pepper, and chili flakes.","Spread mashed avocado on toast, top with eggs."]},
"Protein Pancakes":{prepTime:"5 mins",cookTime:"12 mins",steps:["Blend rolled oats into a flour in a blender.","Add eggs, mashed banana, greek yogurt, and a splash of whole milk to the blender and mix until smooth.","Heat a non-stick pan over medium heat and lightly grease.","Pour batter to form 3 pancakes, cook 2-3 minutes per side until golden.","Stack pancakes, top with granola, blueberries, and strawberries. Drizzle with maple syrup."]},
"Breakfast Burrito":{prepTime:"10 mins",cookTime:"10 mins",steps:["Scramble the eggs in a pan over medium heat until just set.","Warm the black beans in a small saucepan or microwave.","Warm the tortilla in a dry pan for 30 seconds per side.","Layer scrambled eggs, black beans, cheddar cheese, and sliced avocado on the tortilla.","Roll up tightly, tucking in the sides, and serve."]},
"Shakshuka Breakfast":{prepTime:"10 mins",cookTime:"20 mins",steps:["Dice the onion and bell pepper.","Heat a skillet over medium heat, saut\u00e9 onion and bell pepper until soft, about 5 minutes.","Pour in tomato sauce and simmer for 5 minutes.","Make wells in the sauce and crack eggs into them.","Cover and cook for 8-10 minutes until egg whites are set.","Crumble feta cheese on top and serve with warm pita bread."]},
"Japanese Tamagoyaki":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Whisk eggs with soy sauce and a pinch of sugar.","Heat a rectangular or small pan over medium-low heat and lightly oil.","Pour a thin layer of egg mixture, cook until just set, then roll to one side.","Repeat with remaining egg mixture, rolling each layer around the previous one.","Slice tamagoyaki into rounds and serve with rice, miso soup made from miso paste, and sliced green onion."]},
"Smoothie Bowl":{prepTime:"10 mins",cookTime:"0 mins",steps:["Peel and freeze the banana in advance for best results.","Blend frozen banana, blueberries, greek yogurt, rolled oats, and a splash of whole milk until thick and creamy.","Pour into a bowl.","Top with granola, mango, strawberries, and a drizzle of honey and maple syrup.","Serve immediately before it melts."]},
"Egg & Potato Paratha":{prepTime:"10 mins",cookTime:"15 mins",steps:["Boil potato until fork-tender, about 12 minutes. Peel and mash roughly.","Mix mashed potato with diced onion, salt, cumin, and turmeric.","Warm tortilla in a dry pan, spread potato filling on one half.","Fry eggs sunny-side up or scrambled in butter.","Place eggs on top of the potato-filled tortilla, fold over.","Press and cook for 2 minutes per side until golden and crispy."]},
"Chilaquiles":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cut corn tortillas into triangles and fry or bake until crispy.","Simmer tomato sauce with a pinch of cumin in a large skillet.","Add tortilla chips to the sauce and toss to coat.","Fry eggs in a separate pan to your liking.","Plate the sauced tortillas, top with fried eggs, diced onion, sliced avocado, and crumbled feta."]},
"French Toast":{prepTime:"5 mins",cookTime:"10 mins",steps:["Whisk together eggs, milk, and a pinch of cinnamon in a shallow dish. Mix in crushed rolled oats.","Dip bread slices in the oat-egg mixture, soaking each side for 10 seconds.","Melt butter in a pan over medium heat.","Cook bread slices 2-3 minutes per side until golden brown.","Serve topped with sliced strawberries, blueberries, sliced banana, and granola. Drizzle with maple syrup."]},
"Huevos Rancheros":{prepTime:"10 mins",cookTime:"15 mins",steps:["Warm corn tortillas in a dry pan until pliable.","Heat black beans in a small pot with a pinch of cumin and a splash of water.","Warm tomato sauce in a skillet.","Fry eggs sunny-side up in a lightly oiled pan.","Layer tortillas with beans, fried eggs, and warm tomato sauce.","Top with sliced avocado and crumbled feta cheese."]},
"Grilled Chicken & Rice Bowl":{prepTime:"10 mins",cookTime:"30 mins",steps:["Cook brown rice according to package directions.","Season the chicken with salt, pepper, and a drizzle of olive oil.","Grill or pan-sear chicken over medium-high heat, 6-7 minutes per side until cooked through.","Steam or blanch broccoli florets until tender-crisp, about 4 minutes.","Slice the chicken and assemble bowls with rice, broccoli, and chicken.","Drizzle with remaining olive oil."]},
"Spaghetti Bolognese":{prepTime:"10 mins",cookTime:"30 mins",steps:["Cook spaghetti in salted boiling water according to package directions.","Dice the onion finely.","Brown ground beef in a large pan over medium-high heat, breaking it apart.","Add diced onion and cook until softened, about 3 minutes.","Pour in tomato sauce and drained white beans, season with oregano, dried basil, salt, and pepper. Simmer for 15 minutes.","Drain pasta, toss with the sauce, and top with grated parmesan."]},
"Chicken Burrito Bowl":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook brown rice according to package directions.","Season the chicken with cumin and chili powder. Grill or pan-sear until cooked through, about 6-7 minutes per side.","Warm black beans in a small pot.","Dice bell pepper and slice avocado. Cook corn in a hot dry pan for 2 minutes for a charred effect.","Slice the chicken and assemble bowls with rice, beans, bell pepper, corn, and avocado. Garnish with cilantro."]},
"Teriyaki Salmon Bowl":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook white rice according to package directions.","Pat salmon dry and season with salt and pepper.","Pan-sear salmon skin-side down in a hot oiled pan for 4 minutes, flip and cook 3 more minutes.","Glaze salmon with a mixture of soy sauce and honey during the last minute of cooking.","Cook edamame in boiling water for 3 minutes, then drain.","Assemble bowls with rice, salmon, and edamame."]},
"Chicken Tikka Masala":{prepTime:"15 mins",cookTime:"30 mins",steps:["Cut the chicken into bite-sized pieces and marinate in greek yogurt with cumin, turmeric, garam masala, and coriander for at least 10 minutes.","Dice the onion.","Heat olive oil in a large pan and cook chicken pieces until browned on all sides.","In the same pan, saut\u00e9 onion until golden, then add tomato sauce and cauliflower florets.","Return chicken to the sauce and simmer for 15-20 minutes.","Serve over cooked basmati rice."]},
"Falafel Plate":{prepTime:"20 mins",cookTime:"15 mins",steps:["Drain and rinse chickpeas, then pulse in a food processor with cumin, coriander, and parsley until coarsely ground.","Form mixture into small patties or balls.","Pan-fry falafel in a bit of oil over medium heat, 3-4 minutes per side until golden.","Dice cucumber for a simple salad.","Arrange falafel on a plate with salad, warm pita bread, hummus, and a drizzle of tahini."]},
"Greek Chicken Salad":{prepTime:"10 mins",cookTime:"15 mins",steps:["Season chicken breast with oregano, salt, and pepper.","Grill or pan-sear chicken until cooked through, 6-7 minutes per side. Let rest, then slice.","Dice cucumber and red onion.","Crumble feta cheese.","Toss romaine lettuce with the diced vegetables, olive oil, and a squeeze of lemon.","Arrange salad on a plate and top with sliced chicken and feta."]},
"Beef Stir Fry":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook brown rice according to package directions.","Slice beef sirloin into thin strips against the grain.","Slice bell pepper. Cut broccoli, cauliflower, and asparagus into small florets and pieces.","Heat sesame oil in a wok over high heat, sear beef strips for 2 minutes, set aside.","Stir-fry bell pepper, broccoli, cauliflower, and asparagus for 3-4 minutes.","Return beef to wok, add soy sauce, toss together, and serve over rice."]},
"Carnitas Tacos":{prepTime:"10 mins",cookTime:"3 hrs",steps:["Season the pork with cumin, oregano, salt, and pepper.","Place in a slow cooker or Dutch oven with a splash of water and orange juice.","Cook on low for 3 hours until fork-tender, then shred with two forks.","Warm corn tortillas in a dry pan.","Fill tortillas with shredded pork, coleslaw mix, diced onion, and fresh cilantro.","Serve with lime wedges for squeezing over tacos."]},
"Miso Ramen":{prepTime:"10 mins",cookTime:"20 mins",steps:["Bring a pot of water to a boil and cook rice noodles according to package. Drain and set aside.","Slice the pork thinly and sear in a hot pan until browned.","Dissolve miso paste in 3 cups of hot broth or water.","Bring miso broth to a gentle simmer, add spinach and cook 1 minute.","Soft-boil an egg (6-7 minutes), peel and halve.","Assemble bowls with noodles, miso broth, pork, egg, and sliced green onion."]},
"Palak Paneer":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook brown rice according to package directions.","Blanch spinach in boiling water for 2 minutes, then blend into a smooth puree.","Dice onion and mince garlic.","Saut\u00e9 onion and garlic in oil until golden.","Add spinach puree, cumin, garam masala, and turmeric. Simmer for 5 minutes.","Cube paneer, add to the sauce, and cook for 5 more minutes. Serve over rice."]},
"Shawarma Bowl":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Slice the chicken into strips and season with cumin, paprika, turmeric, cinnamon, and allspice.","Mix the seasoned chicken with greek yogurt and let marinate briefly.","Cook chicken in a hot skillet for 5-6 minutes until browned and cooked through.","Squeeze lemon juice over the cooked chicken.","Dice cucumber. Drain and rinse chickpeas.","Assemble bowls with rice, chicken, hummus, cucumber, and chickpeas."]},
"Kimchi Fried Rice":{prepTime:"5 mins",cookTime:"10 mins",steps:["Dice the pork into small pieces.","Heat sesame oil in a wok, cook the pork until browned, about 4 minutes.","Add chopped kimchi and a pinch of gochugaru. Stir-fry for 2 minutes.","Add cooked rice and toss everything together over high heat.","Push rice to the side, fry an egg in the center of the wok.","Plate rice topped with the fried egg and sliced green onion."]},
"Lamb & Lentil Soup":{prepTime:"10 mins",cookTime:"30 mins",steps:["Dice onion, carrot, and potato. Mince garlic.","Heat olive oil in a large pot. Brown ground lamb for 4-5 minutes, breaking it apart.","Add onion, garlic, and carrot. Cook 2 minutes.","Add red lentils, diced potato, tomato sauce, and 3 cups water or broth.","Bring to a boil, then reduce heat and simmer for 25 minutes until lentils are soft.","Season with salt and pepper, blend partially if desired."]},
"Pork Club Wrap":{prepTime:"10 mins",cookTime:"10 mins",steps:["Slice pork loin thinly and sear in a hot pan for 2-3 minutes per side.","Warm the tortilla in a dry pan or microwave for 15 seconds.","Layer sliced pork loin on the tortilla.","Slice avocado.","Add spinach and avocado on top of the pork.","Roll up tightly, tucking in the sides. Slice in half and serve."]},
"Shrimp Primavera":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook penne pasta in salted boiling water according to package directions.","Peel and devein shrimp. Dice zucchini and bell pepper.","Heat olive oil in a large pan. Sear shrimp for 2-3 minutes per side until pink. Set aside.","Saut\u00e9 zucchini and bell pepper for 4-5 minutes.","Toss drained pasta with vegetables, shrimp, grated parmesan, and a pinch of dried basil.","Season with salt and pepper."]},
"Shrimp Tacos":{prepTime:"10 mins",cookTime:"10 mins",steps:["Season shrimp with salt, pepper, and cumin.","Sear shrimp in a hot oiled pan for 2-3 minutes per side until pink.","Warm corn tortillas in a dry pan.","Shred cabbage thinly.","Fill tortillas with shrimp, cabbage, coleslaw, and sliced avocado.","Serve with lime wedges."]},
"Chicken Stir Fry":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook brown rice according to package directions.","Cut chicken breast into bite-sized pieces.","Heat sesame oil in a wok, cook chicken until golden on all sides, about 6-8 minutes.","Add broccoli florets, sliced carrot, green beans, and edamame, stir-fry 4-5 minutes.","Add soy sauce and toss everything together.","Serve over rice."]},
"Lamb Kofta Plate":{prepTime:"15 mins",cookTime:"12 mins",steps:["Mix ground lamb with cumin, paprika, coriander, minced onion, and salt.","Form mixture into oval-shaped kofta patties or cylinders.","Grill or pan-fry kofta for 4-5 minutes per side until cooked through.","Dice red onion.","Arrange kofta on a plate with hummus, warm pita bread, and red onion. Drizzle with tahini."]},
"Japchae":{prepTime:"15 mins",cookTime:"15 mins",steps:["Soak sweet potato noodles in warm water for 10 minutes, then cook in boiling water for 5-6 minutes. Drain and cut with scissors.","Slice beef sirloin into thin strips. Marinate with soy sauce, sesame oil, and a pinch of sugar.","Blanch spinach for 30 seconds, drain and squeeze dry. Season with sesame oil and salt.","Julienne carrot and bell pepper.","Stir-fry beef in a hot pan for 2-3 minutes until browned. Remove. Stir-fry vegetables for 2-3 minutes.","Toss noodles, beef, spinach, and vegetables together. Season with soy sauce and sesame oil."]},
"Brown Rice Power Bowl":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook brown rice in water according to package directions.","Peel and cube sweet potato, toss with olive oil and roast at 200\u00b0C (400\u00b0F) for 20 minutes.","Season and grill or pan-sear chicken breast until cooked through, then slice.","Arrange bowls with brown rice, roasted sweet potato, sliced chicken, and fresh spinach.","Drizzle with remaining olive oil."]},
"BBQ Chicken Plate":{prepTime:"10 mins",cookTime:"35 mins",steps:["Peel and cube sweet potato, roast at 200\u00b0C (400\u00b0F) for 25 minutes.","Season the chicken with salt, pepper, and paprika.","Grill or bake chicken for 20-25 minutes until cooked through.","Brush chicken with BBQ sauce during the last 5 minutes of cooking.","Toss coleslaw mix with a light dressing.","Serve chicken with roasted sweet potato and coleslaw."]},
"Chana Masala":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook brown rice according to package directions.","Dice onion and mince garlic.","Heat olive oil in a pan, saut\u00e9 onion and garlic until golden.","Add cumin, turmeric, garam masala, coriander, and chili powder. Toast for 30 seconds. Add diced eggplant and cauliflower florets, sauté 3-4 minutes.","Add chickpeas, red lentils, paneer cubes, and tomato sauce. Simmer for 15-20 minutes.","Serve over rice."]},
"Poke Bowl":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cook white rice and let it cool slightly.","Cut ahi tuna and salmon fillet into 1cm cubes.","Whisk soy sauce, miso paste, and a dash of sesame oil into a marinade. Marinate the tuna and salmon for 5 minutes.","Slice avocado, cucumber, and mango.","Cook edamame in boiling water for 3 minutes, drain.","Assemble bowls with rice, marinated tuna and salmon, avocado, cucumber, mango, and edamame."]},
"Bulgogi Rice Bowl":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Slice beef sirloin thinly and marinate in soy sauce, sesame oil, grated ginger, and a pinch of sugar for 10 minutes. Cook sweet potato noodles per package directions, drain.","Julienne carrot and slice green onion.","Cook marinated beef in a hot skillet for 3-4 minutes until caramelized.","Assemble bowls with rice, sweet potato noodles, bulgogi beef, carrot, and green onion. Serve with kimchi on the side."]},
"Egg Fried Rice":{prepTime:"5 mins",cookTime:"10 mins",steps:["Use day-old cooked rice for best results.","Heat sesame oil in a wok over high heat.","Dice the pork into small pieces and cook in the wok until browned, about 3-4 minutes.","Scramble eggs in the wok, break into small pieces.","Add rice and green peas, stir-fry for 3-4 minutes.","Add diced carrot and soy sauce, toss until heated through.","Serve immediately."]},
"Tuna Nicoise Salad":{prepTime:"15 mins",cookTime:"15 mins",steps:["Boil potato until tender, about 12 minutes. Slice when cool.","Hard-boil egg for 10 minutes, peel and quarter.","Blanch green beans for 3 minutes, then cool in ice water.","Arrange potato, egg, green beans, and drained tuna on a plate.","Drizzle with olive oil and season with salt and pepper."]},
"Chicken Quesadilla":{prepTime:"10 mins",cookTime:"15 mins",steps:["Season and cook chicken breast in a pan until done, then dice.","Dice bell pepper and onion, saut\u00e9 until softened.","Place tortilla in a dry pan, add chicken, vegetables, cheddar cheese, and a drizzle of BBQ sauce on one half.","Fold tortilla over and cook 2-3 minutes per side until golden and cheese melts.","Let rest for 1 minute, then cut into wedges."]},
"Lamb & Hummus Wrap":{prepTime:"10 mins",cookTime:"10 mins",steps:["Season ground lamb with cumin, paprika, salt, and pepper. Cook in a skillet over medium-high heat for 5-6 minutes until browned.","Warm the tortilla briefly in a dry pan or microwave.","Spread hummus generously over the tortilla.","Slice cucumber and carrot into thin sticks.","Layer cooked lamb, spinach, cucumber, and carrot on top.","Roll up tightly, tucking in the sides. Slice in half and serve."]},
"Chicken Caesar Salad":{prepTime:"10 mins",cookTime:"15 mins",steps:["Season chicken breast with salt, pepper, and garlic powder.","Grill or pan-sear chicken 6-7 minutes per side until cooked through. Let rest, then slice.","Wash and chop romaine lettuce.","Toss lettuce with olive oil and a squeeze of lemon as dressing.","Cube whole wheat bread and toast until crisp to make croutons.","Top with sliced chicken, shaved parmesan, and the croutons."]},
"Lamb Shawarma Wrap":{prepTime:"10 mins",cookTime:"12 mins",steps:["Season ground lamb with cumin, paprika, turmeric, cinnamon, and allspice. Form into a flat patty or crumbles.","Cook lamb in a hot skillet until browned and cooked through, about 8 minutes.","Warm the tortilla in a dry pan.","Slice red onion.","Layer lamb, red onion, and a drizzle of tahini on the tortilla.","Roll up tightly and serve."]},
"Shrimp Fried Rice":{prepTime:"10 mins",cookTime:"10 mins",steps:["Use day-old cooked rice for best results.","Peel and devein shrimp.","Heat sesame oil in a wok over high heat, cook shrimp 2 minutes per side, set aside.","Scramble egg in the wok, break apart.","Add rice and green peas, stir-fry for 3 minutes.","Return shrimp, add soy sauce, and toss until combined."]},
"Butter Chicken":{prepTime:"15 mins",cookTime:"25 mins",steps:["Cook basmati rice according to package directions.","Cut the chicken into bite-sized pieces.","Melt butter in a large pan and sear chicken until golden on all sides.","Add tomato sauce, cumin, turmeric, garam masala, and coriander. Simmer for 10 minutes.","Stir in greek yogurt and cook for 5 more minutes on low heat.","Serve over rice."]},
"Mediterranean Stuffed Peppers":{prepTime:"15 mins",cookTime:"30 mins",steps:["Preheat oven to 190\u00b0C (375\u00b0F).","Cook brown rice according to package directions.","Brown ground beef in a skillet with cumin and oregano.","Mix cooked brown rice, beef, tomato sauce, and half the feta.","Cut bell peppers in half and remove seeds.","Stuff peppers with the mixture, top with remaining feta, and bake for 25 minutes."]},
"Korean Chicken Wings":{prepTime:"10 mins",cookTime:"30 mins",steps:["Cook white rice according to package directions.","Pat the chicken dry and season with gochugaru, salt, and pepper.","Bake the chicken at 220\u00b0C (425\u00b0F) for 25-30 minutes until crispy, flipping halfway.","Mix soy sauce, honey, BBQ sauce, minced garlic, and sesame oil for the glaze.","Toss baked chicken in the glaze.","Serve chicken over rice."]},
"Spaghetti alle Vongole":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook spaghetti in salted boiling water until al dente. Reserve 1 cup of pasta water.","Peel and devein shrimp (or scrub clams if using). Mince garlic.","Heat olive oil in a large skillet over medium-high heat. Saut\u00e9 garlic for 30 seconds.","Add shrimp and cook 2-3 minutes per side until pink and curled.","Add a splash of pasta water and squeeze of lemon juice, toss with cooked spaghetti.","Season with chili flakes, parsley, salt and pepper. Serve immediately."]},
"Chicken Enchiladas":{prepTime:"15 mins",cookTime:"25 mins",steps:["Preheat oven to 190\u00b0C (375\u00b0F).","Cook brown rice according to package directions.","Cook and shred the chicken, or dice finely. Season with cumin and chili powder.","Mix chicken with diced onion and half the cheddar cheese.","Warm corn tortillas briefly to make them pliable.","Fill tortillas with chicken mixture, roll up, and place seam-side down in a baking dish.","Pour tomato sauce over enchiladas, top with remaining cheddar and shredded mozzarella, and bake for 20 minutes. Serve with rice on the side."]},
"Sushi Bowl (Chirashi)":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cook white rice and season with a splash of rice vinegar while warm.","Slice the fish and ahi tuna into thin pieces.","Slice avocado and cucumber.","Cook edamame in boiling water for 3 minutes, drain.","Arrange rice in a bowl and artfully top with the fish, ahi tuna, avocado, cucumber, and edamame.","Serve with soy sauce on the side."]},
"Aloo Gobi":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook brown rice according to package directions.","Peel and cube potato. Cut cauliflower into florets.","Dice onion.","Heat olive oil in a pan, saut\u00e9 onion until golden.","Add potato, cauliflower, tomato sauce, cumin, turmeric, coriander, and chili powder. Cover and cook for 20 minutes, stirring occasionally.","Serve over rice."]},
"Tabbouleh with Grilled Chicken":{prepTime:"15 mins",cookTime:"20 mins",steps:["Cook brown rice according to package directions and let cool.","Season and grill chicken breast until cooked through, then dice.","Finely dice cucumber.","Toss cooled brown rice with cucumber, chickpeas, olive oil, and lemon juice.","Season with salt and pepper.","Top tabbouleh with diced grilled chicken."]},
"Pork Tonkatsu":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Pound pork loin to even thickness and season with salt and pepper.","Set up breading station: flour, beaten egg, panko breadcrumbs.","Coat pork in flour, dip in egg, then press into panko.","Pan-fry in oil over medium-high heat for 3-4 minutes per side until golden and crispy.","Steam asparagus for 4 minutes until tender-crisp. Slice tonkatsu and serve with rice, shredded cabbage, and asparagus."]},
"Thai Basil Chicken":{prepTime:"10 mins",cookTime:"10 mins",steps:["Cook white rice according to package directions.","Dice the chicken into small pieces.","Mince garlic and slice bell pepper.","Heat sesame oil in a wok over high heat, cook chicken until browned.","Add garlic, bell pepper, and soy sauce. Stir-fry for 3-4 minutes.","Serve over rice."]},
"Tuscan White Bean Soup":{prepTime:"10 mins",cookTime:"20 mins",steps:["Slice pork loin into small pieces. Mince garlic.","Heat olive oil in a large pot. Brown pork for 3-4 minutes. Add garlic and cook 1 minute.","Add white beans, tomato sauce, oregano, and 2 cups water or broth.","Simmer for 15 minutes.","Stir in spinach and cook until wilted, about 2 minutes.","Toast whole wheat bread and serve soup with bread on the side."]},
"Mango Chicken Curry":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook brown rice according to package directions.","Cut the chicken into pieces and dice onion.","Saut\u00e9 onion in oil until softened, add chicken and brown on all sides.","Add coconut milk, diced mango, cumin, turmeric, and garam masala.","Simmer for 15-20 minutes until chicken is cooked and sauce thickens.","Serve over rice."]},
"Grilled Salmon & Asparagus":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook brown rice according to package directions.","Trim asparagus ends and toss with olive oil, salt, and pepper.","Season the salmon with salt, pepper, and lemon juice.","Grill or bake the salmon and asparagus at 200\u00b0C (400\u00b0F) for 12-15 minutes.","Plate brown rice, top with the salmon and asparagus. Drizzle pesto sauce over the salmon.","Squeeze fresh lemon over everything."]},
"Beef Tacos":{prepTime:"10 mins",cookTime:"12 mins",steps:["Brown ground beef in a skillet over medium-high heat, breaking it apart.","Season with cumin, chili powder, salt, and pepper.","Dice onion and avocado.","Warm corn tortillas in a dry pan.","Drizzle BBQ sauce over the beef. Fill tortillas with seasoned beef, onion, avocado, and cilantro.","Serve immediately."]},
"Chicken Pesto Pasta":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook pasta according to package directions.","Season and pan-sear chicken breast until cooked through, then slice.","Toss drained pasta with pesto sauce.","Top with sliced chicken, mozzarella cheese, and grated parmesan cheese."]},
"Katsu Curry":{prepTime:"15 mins",cookTime:"25 mins",steps:["Cook white rice according to package directions.","Dice onion and carrot for the curry sauce.","Saut\u00e9 onion and carrot in oil, add curry powder and water, simmer for 15 minutes.","Pound chicken breast to even thickness, coat in flour, beaten egg, then panko.","Pan-fry chicken for 3-4 minutes per side until golden and crispy.","Slice katsu and serve with rice and curry sauce."]},
"Spicy Tuna Bowl":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cook white rice and let it cool slightly.","Cut ahi tuna into cubes.","Mix tuna with soy sauce, sesame oil, and chili flakes.","Slice avocado and cucumber.","Assemble bowls with rice, spicy tuna, avocado, and cucumber.","Drizzle with extra sesame oil if desired."]},
"Steak & Sweet Potato":{prepTime:"10 mins",cookTime:"30 mins",steps:["Peel and cube sweet potato, toss with a little oil and roast at 200\u00b0C (400\u00b0F) for 25 minutes.","Season beef sirloin with salt and pepper.","Sear steak in a hot pan with butter for 3-4 minutes per side for medium.","Let steak rest for 5 minutes, then slice.","Steam broccoli until tender-crisp, about 4 minutes.","Serve sliced steak with sweet potato and broccoli."]},
"Chicken Lettuce Wraps with Rice":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook white rice according to package directions.","Dice chicken breast into small pieces.","Heat oil in a wok, cook chicken until browned.","Add soy sauce and cook 1 more minute.","Grate or julienne carrot.","Separate romaine lettuce leaves to use as cups.","Fill lettuce cups with chicken, carrot, and coleslaw mix. Squeeze lime over top. Serve with rice on the side."]},
"Dal Tadka":{prepTime:"10 mins",cookTime:"30 mins",steps:["Cook brown rice according to package directions.","Rinse red lentils and cook in 2.5 cups water until soft, about 20 minutes.","Dice onion and mince garlic.","Heat butter in a small pan, saut\u00e9 garlic and onion until golden (this is the tadka).","Add tomato sauce, cumin, turmeric, and chili powder to the tadka, cook 2 minutes.","Pour the tadka over the cooked lentils, stir, and serve over rice."]},
"Baba Ganoush Plate":{prepTime:"10 mins",cookTime:"30 mins",steps:["Roast whole eggplant at 220\u00b0C (425\u00b0F) for 25-30 minutes until completely soft.","Scoop out eggplant flesh and mash with tahini, olive oil, and lemon juice.","Season with salt, pepper, and a pinch of cumin.","Dice cucumber.","Arrange baba ganoush on a plate with cucumber and warm pita bread."]},
"Dakgalbi":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook white rice according to package directions.","Cut the chicken into bite-sized pieces.","Peel and cube sweet potato, slice cabbage.","Stir-fry chicken in sesame oil with gochugaru and gochujang until nearly cooked.","Add sweet potato, cabbage, and sweet potato noodles. Cook for 10-12 minutes until vegetables are tender and noodles cooked through.","Serve over rice with kimchi on the side."]},
"Pork Milanese":{prepTime:"10 mins",cookTime:"15 mins",steps:["Pound pork loin between plastic wrap to 1cm thickness.","Set up breading station: flour, beaten egg, panko breadcrumbs.","Dredge pork in flour, dip in egg, coat in panko.","Heat olive oil in a large skillet over medium-high heat.","Fry breaded pork for 3-4 minutes per side until golden and cooked through (internal temp 63\u00b0C/145\u00b0F).","Serve on a bed of spinach with tomato sauce and a squeeze of lemon."]},
"Black Bean Bowl":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook brown rice according to package directions.","Warm black beans in a pot with cumin and a pinch of salt.","Slice avocado.","If using fresh corn, saut\u00e9 kernels briefly in a hot pan.","Assemble bowls with rice, beans, avocado, and corn.","Squeeze lime over everything."]},
"Salmon Teriyaki Bento":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook white rice according to package directions.","Pat the salmon dry and season with salt and pepper.","Whisk soy sauce, miso paste, and honey for the teriyaki glaze. Pan-sear the salmon for 4 minutes per side, brushing with the glaze in the last minute.","Steam broccoli for 4 minutes until tender-crisp.","Cook edamame in boiling water for 3 minutes, drain.","Arrange rice, salmon, broccoli, and edamame in a bento box or plate."]},
"Chicken Alfredo":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook pasta according to package directions. Reserve 1 cup pasta water.","Season and pan-sear the chicken until cooked through, then slice.","Melt butter in a large pan, saut\u00e9 minced garlic for 1 minute.","Add pasta water gradually and stir in grated parmesan until a creamy sauce forms.","Steam asparagus for 4 minutes until tender, then toss with pasta in the sauce.","Top with sliced chicken."]},
"Lamb Biryani":{prepTime:"15 mins",cookTime:"35 mins",steps:["Wash and soak basmati rice for 10 minutes, then parboil until 70% cooked. Drain.","Brown ground lamb in a pot with diced onion and minced garlic.","Add greek yogurt, cumin, turmeric, garam masala, cardamom, cinnamon, and bay leaf, cook for 5 minutes.","Layer parboiled rice over the lamb mixture.","Cover tightly and cook on low heat for 15-20 minutes until rice is fully cooked.","Fluff gently and serve."]},
"Shrimp & Feta Salad":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook brown rice according to package directions and let cool.","Peel and devein shrimp.","Sear shrimp 2-3 minutes per side until pink.","Dice cucumber.","Toss brown rice with cucumber, olive oil, lemon juice, a pinch of oregano, and crumbled feta.","Top salad with warm shrimp."]},
"Meatball Sub":{prepTime:"15 mins",cookTime:"20 mins",steps:["Mix ground beef with breadcrumbs, salt, pepper, and a beaten egg. Form into meatballs.","Brown meatballs in a pan on all sides, about 5 minutes.","Add tomato sauce, cover, and simmer for 15 minutes until meatballs are cooked through.","Split the sub roll and toast lightly.","Fill the roll with meatballs and sauce.","Top with sliced mozzarella and broil briefly until cheese melts."]},
"Chicken Shawarma Plate":{prepTime:"15 mins",cookTime:"15 mins",steps:["Slice chicken breast into strips and marinate with cumin, paprika, turmeric, cinnamon, allspice, and olive oil.","Cook chicken in a hot skillet for 5-6 minutes until browned and cooked through.","Warm pita bread in a dry pan.","Dice cucumber.","Arrange chicken on a plate with pita, hummus, cucumber, and a drizzle of tahini."]},
"Shrimp Fra Diavolo":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook pasta in salted boiling water until al dente. Drain, reserving pasta water.","Peel and devein shrimp. Mince garlic and dice onion.","Heat olive oil in a large skillet. Saute onion and garlic for 2-3 minutes.","Add tomato sauce and a pinch of chili flakes. Simmer for 10 minutes.","Add shrimp and cook 3-4 minutes until pink and curled.","Toss with pasta, adding a splash of pasta water to coat. Serve immediately."]},
"Cobb Salad":{prepTime:"15 mins",cookTime:"15 mins",steps:["Season and grill or pan-sear chicken breast until cooked through, then dice.","Hard-boil egg for 10 minutes, peel and quarter.","Dice avocado.","Chop romaine lettuce and arrange on a plate.","Arrange rows of chicken, egg, avocado, and crumbled cheddar on the lettuce.","Drizzle with olive oil and season with salt and pepper."]},
"Veggie Sushi Wrap":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cook white rice and season with rice vinegar while warm. Let cool.","Julienne cucumber, carrot, and slice avocado thinly.","Warm a tortilla in a dry pan.","Spread seasoned rice over the tortilla and arrange vegetables in a line.","Roll tightly into a wrap. Slice in half.","Serve with soy sauce."]},
"Chipotle Chicken Bowl":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook brown rice according to package directions.","Season the chicken with cumin, paprika, chili powder, and garlic powder. Cook in a hot pan for 6-7 minutes per side.","Warm black beans in a pot.","Dice avocado. Cook corn in a hot dry pan for a charred effect.","Slice chicken and assemble bowls with rice, beans, corn, chicken, and avocado. Garnish with cilantro."]},
"Minestrone Soup":{prepTime:"10 mins",cookTime:"25 mins",steps:["Slice pork loin into small pieces. Dice zucchini, carrot, eggplant, and potato.","Heat olive oil in a large pot, brown pork for 3-4 minutes. Add carrot and cook 3 minutes.","Add zucchini, eggplant, potato, tomato sauce, and 3 cups water or broth.","Add white beans, red lentils, pasta, oregano, and dried basil. Simmer for 15 minutes.","Stir in spinach and cook 2 more minutes until wilted.","Season with salt and pepper."]},
"Saag Chicken":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook basmati rice according to package directions.","Blanch spinach, then blend into a smooth puree.","Dice onion and cut chicken breast into pieces.","Saut\u00e9 onion until golden, add chicken and cook until browned.","Add spinach puree, greek yogurt, cauliflower florets, paneer cubes, cumin, turmeric, garam masala, and coriander. Simmer for 15 minutes.","Serve over rice."]},
"Stuffed Grape Leaves":{prepTime:"20 mins",cookTime:"40 mins",steps:["Mix cooked white rice with ground lamb, diced onion, allspice, and cinnamon.","Blanch grape leaves briefly in boiling water and pat dry.","Place a spoonful of filling on each leaf and roll tightly, tucking in sides.","Layer stuffed leaves seam-side down in a pot.","Add olive oil, lemon juice, and enough water to just cover.","Cover and simmer on low for 35-40 minutes."]},
"Doenjang Jjigae":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook white rice according to package directions.","Slice pork belly into thin pieces. Slice zucchini and onion.","Brown pork belly in the pot for 3-4 minutes until crispy. Dissolve miso paste (doenjang) in 2 cups of water or anchovy broth.","Bring to a boil and add zucchini and onion.","Simmer for 15 minutes until vegetables are tender.","Serve stew alongside rice with kimchi on the side."]},
"Chicken Souvlaki Plate":{prepTime:"15 mins",cookTime:"12 mins",steps:["Cut chicken breast into cubes and marinate with olive oil, oregano, lemon juice, salt, and pepper.","Thread chicken onto skewers if desired.","Grill or pan-sear chicken for 10-12 minutes, turning occasionally, until cooked through.","Dice cucumber and red onion.","Mix greek yogurt with a pinch of garlic and salt for tzatziki.","Serve chicken with warm pita, tzatziki, and diced vegetables."]},
"Pulled Pork Sandwich":{prepTime:"10 mins",cookTime:"3 hrs",steps:["Season the pork generously with salt, pepper, and smoked paprika.","Place in a slow cooker or Dutch oven with a splash of liquid, cover tightly.","Cook on low for 3 hours until fork-tender.","Shred pork with two forks and toss with BBQ sauce.","Toast the sub rolls.","Pile pulled pork on the rolls and top with coleslaw mix."]},
"Shrimp Scampi":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook spaghetti according to package directions.","Peel and devein shrimp. Mince garlic.","Melt butter in a large skillet, saut\u00e9 garlic for 1 minute.","Add shrimp and cook 2-3 minutes per side until pink.","Squeeze in lemon juice and toss with drained pasta.","Season with salt, pepper, and parsley if desired."]},
"Shrimp & Veggie Stir Fry":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook brown rice according to package directions.","Peel and devein shrimp. Slice bell pepper, carrot, and zucchini.","Heat sesame oil in a wok, cook shrimp until pink on all sides, about 2-3 minutes per side. Set aside.","Add vegetables and stir-fry for 4-5 minutes.","Return shrimp, add soy sauce and toss everything together.","Serve over rice."]},
"Chicken Fried Rice":{prepTime:"10 mins",cookTime:"10 mins",steps:["Use day-old cooked rice for best results. Dice chicken breast.","Heat sesame oil in a wok over high heat, cook chicken until done, set aside.","Scramble egg in the wok, break apart.","Add rice, green peas, and diced carrot, stir-fry for 3-4 minutes.","Return chicken, add soy sauce, and toss until combined.","Serve immediately."]},
// Removed: Mujaddara cooking instructions
"Chicken Korma":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook basmati rice according to package directions.","Cut the chicken into pieces and dice onion.","Saut\u00e9 onion in oil until golden, add chicken and brown.","Stir in greek yogurt, coconut milk, cumin, coriander, turmeric, cardamom, and cinnamon.","Simmer for 15-20 minutes until chicken is cooked through.","Simmer 2 more minutes to thicken, then serve over rice."]},
"Beef Bulgogi Noodle Bowl":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Cook rice noodles according to package directions, drain.","Slice beef sirloin thinly and marinate in soy sauce, sesame oil, garlic, and a pinch of sugar.","Cook beef in a hot skillet for 3-4 minutes until caramelized.","Julienne carrot.","Assemble bowls with rice, rice noodles, bulgogi beef, and carrot."]},
"Beef Meatballs & Zoodles":{prepTime:"15 mins",cookTime:"20 mins",steps:["Mix ground beef with salt, pepper, and oregano and dried basil. Form into meatballs.","Brown meatballs in olive oil on all sides.","Add tomato sauce, cover, and simmer for 15 minutes until meatballs are cooked through.","Spiralize or ribbon-cut zucchini into zoodles.","Saut\u00e9 zoodles briefly in a hot pan for 2 minutes.","Serve meatballs and sauce over zoodles with grated parmesan."]},
"Lamb Tagine":{prepTime:"10 mins",cookTime:"35 mins",steps:["Dice onion and mince garlic. Dice carrot into small pieces.","Heat olive oil in a tagine or heavy pot over medium-high heat. Brown ground lamb for 5 minutes, breaking it apart. Drain excess fat.","Add onion, garlic, and carrot. Saut\u00e9 for 3-4 minutes until softened.","Add tomato sauce, drained chickpeas, drained white beans, cubed eggplant, and cumin, cinnamon, ginger, turmeric, and paprika. Add 1 cup water.","Cover and simmer for 25 minutes until sauce thickens and flavors meld.","Season with salt and pepper. Serve in a bowl."]},
"Pesto Shrimp Pasta":{prepTime:"10 mins",cookTime:"15 mins",steps:["Bring a pot of salted water to a boil. Cook pasta according to package directions until al dente. Drain.","Peel and devein shrimp. Sear in a hot pan for 2-3 minutes per side until pink.","Toss hot pasta with pesto sauce and shrimp in a bowl.","Top with grated parmesan cheese and serve immediately."]},
"Asian Noodle Soup":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook rice noodles according to package directions, drain.","Slice the chicken and sear in a pot until browned.","Add 3 cups water or dashi broth and soy sauce, bring to a simmer.","Add spinach and cook for 1 minute.","Soft-boil an egg (6-7 minutes), peel and halve.","Place noodles in bowls, ladle broth and chicken over them, top with egg and green onion."]},
"Mediterranean Tuna Salad":{prepTime:"10 mins",cookTime:"0 mins",steps:["Drain canned tuna.","Dice cucumber and thinly slice red onion.","Toss tuna with vegetables, drained white beans, and olive oil.","Season with salt, pepper, and oregano.","Toast whole wheat bread.","Serve salad with toast on the side."]},
"Beef & Broccoli":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Slice beef sirloin into thin strips against the grain.","Cut broccoli into small florets.","Heat sesame oil in a wok over high heat, sear beef for 2 minutes, set aside.","Stir-fry broccoli for 3-4 minutes, add soy sauce.","Return beef to wok, toss together, and serve over rice."]},
"Veggie Burrito":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook brown rice according to package directions.","Warm black beans in a pot with cumin.","Slice bell pepper and avocado.","Warm the tortilla in a dry pan.","Layer rice, black beans, bell pepper, avocado, and cheddar cheese on the tortilla.","Roll up tightly, tucking in the sides, and serve."]},
"Okonomiyaki":{prepTime:"10 mins",cookTime:"15 mins",steps:["Shred cabbage finely and slice green onion.","Mix panko breadcrumbs with water to form a batter.","Stir in shredded cabbage, green onion, and beaten eggs.","Heat a pan and add the thin-sliced pork.","Pour batter over the thin-sliced pork and cook for 5-6 minutes per side until golden and set.","Serve with okonomiyaki sauce and mayonnaise."]},
"Paneer Tikka Wrap":{prepTime:"15 mins",cookTime:"10 mins",steps:["Cut paneer into cubes and marinate in greek yogurt with cumin, turmeric, garam masala, coriander, and chili powder for 10 minutes.","Dice bell pepper and onion.","Grill or pan-sear paneer and vegetables until charred and cooked.","Warm the tortilla in a dry pan.","Arrange paneer and vegetables on the tortilla.","Roll up tightly and serve."]},
"Shrimp Spinach & Rice Salad":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook brown rice according to package directions and let cool.","Peel and devein shrimp. Sear in a hot pan for 2-3 minutes per side until pink.","Wash spinach and toss with a drizzle of olive oil.","Slice avocado.","Toss spinach, brown rice, avocado, and shrimp together.","Drizzle with the remaining olive oil and season with salt and pepper."]},
"Lamb Gyro":{prepTime:"10 mins",cookTime:"15 mins",steps:["Season ground lamb with cumin, oregano, garlic, salt, and pepper.","Cook lamb as crumbles in a hot skillet for 5-6 minutes, set aside.","Season chicken breast with salt, pepper, and oregano. Cook in the same skillet for 4-5 minutes per side, then slice thinly.","Warm pita bread in a dry pan.","Slice red onion and dice cucumber.","Mix greek yogurt with a pinch of garlic and lemon juice for tzatziki.","Fill pita with lamb, sliced chicken, vegetables, and tzatziki."]},
"Lomo Saltado":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cut beef sirloin into thick strips and season with garlic, cumin, salt and pepper. Cut red onion and tomato into thick wedges, and slice the aji amarillo paste into the mix later. Have everything ready before you start - the cooking takes under 5 minutes.","Cut potato into thick batons and fry in hot oil until golden and crisp. Drain, salt, and keep hot.","Cook white rice according to package directions.","Heat a wok or wide steel pan until it is smoking. Add olive oil, then the beef in a single layer. Leave it undisturbed 1-2 minutes to sear hard, then toss. Work in batches so the meat sears rather than steams.","Add red onion and aji amarillo paste and toss 30-60 seconds so the onion stays crisp-tender. Deglaze the pan with red wine vinegar.","Add the tomato wedges and soy sauce and toss just 30 seconds - the tomato should hold its shape and release a little juice.","Fold in the hot fried potatoes (or pile them alongside), scatter with cilantro, and serve immediately with the rice molded to one side."]},
"Pollo Guisado":{prepTime:"10 mins",cookTime:"30 mins",steps:["Cut the chicken into chunks. Dice onion, bell pepper, and potato.","Heat olive oil in a Dutch oven, brown chicken pieces for 3-4 minutes per side.","Add onion, bell pepper, and garlic. Cook 3 minutes until softened.","Add tomato sauce, coconut milk, cumin, oregano, potatoes, and green beans.","Cover and simmer for 20-25 minutes until potatoes are tender and sauce thickens.","Squeeze lime juice over the stew and serve."]},
"Feijoada":{prepTime:"10 mins",cookTime:"40 mins",steps:["Cook white rice according to package directions.","Dice onion and mince garlic. Cut the pork into small cubes.","Heat olive oil in a large pot. Brown pork for 5 minutes on all sides.","Add onion and garlic, cook 3 minutes until softened.","Add drained black beans, a pinch of cumin, and 2 cups water. Simmer for 30 minutes until pork is tender.","Season with salt and pepper, squeeze lime juice, and serve over rice."]},
"Moqueca":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook white rice according to package directions.","Peel and devein shrimp. Dice onion and bell pepper.","Heat olive oil in a deep pan. Saute onion and bell pepper for 3 minutes.","Add tomato sauce and paprika. Cook 2 minutes until softened.","Pour in coconut milk and bring to a simmer. Add shrimp.","Cook for 5-6 minutes until shrimp are pink. Squeeze lime and serve over rice."]},
"Paella Mixta":{prepTime:"15 mins",cookTime:"30 mins",steps:["Dice onion and bell pepper. Mince garlic. Trim green beans and halve.","Heat olive oil in a wide pan. Brown the chicken pieces for 4-5 minutes. Remove.","Saute onion, bell pepper, and garlic for 3 minutes.","Add rice, tomato sauce, paprika, and 2 cups water or broth. Stir once.","Return chicken, add green beans and peas. Do not stir again.","Simmer for 18-20 minutes until rice absorbs liquid. Add shrimp for last 5 minutes. Rest 5 minutes before serving."]},
"Ceviche de Pescado":{prepTime:"20 mins",cookTime:"20 mins",steps:["Boil the sweet potato whole until fork-tender, about 15-20 minutes. Cool and slice into thick rounds. Boil the corn and cut the kernels from the cob.","Slice the red onion very thinly. Salt it, rest 10 minutes, then rinse and drain well to take out the harshness.","Cut the sea bass into even 2cm cubes with a sharp knife. Pat dry - never rinse the fish under water.","Season the fish in a cold bowl with salt, pepper, and minced aji limo, tossing gently.","Squeeze the lime directly over the fish without twisting the rind, which would turn it bitter. Stir gently and let it cure just 2-5 minutes - the cubes should stay translucent at the center, not turn chalky.","Fold in the drained red onion and chopped cilantro. Taste and correct the salt.","Serve immediately and cold, with the sweet potato rounds and corn alongside. The milky juice left in the bowl is the leche de tigre."]},
"Arroz con Pollo":{prepTime:"10 mins",cookTime:"30 mins",steps:["Season the chicken with cumin, oregano, salt, and pepper. Dice onion and bell pepper.","Heat olive oil in a large pot. Brown chicken for 4 minutes per side. Remove.","Saute onion, bell pepper, and garlic for 3 minutes.","Add rice, tomato sauce, coconut milk, green beans, and 1.5 cups water.","Nestle chicken into the rice. Cover and cook 20 minutes until rice is done.","Stir in green peas and cilantro. Rest 5 minutes before serving."]},
"Gambas al Ajillo":{prepTime:"5 mins",cookTime:"10 mins",steps:["Peel and devein shrimp. Thinly slice garlic.","Heat olive oil in a small skillet over medium heat. Add garlic and cook 1 minute until fragrant.","Add shrimp and a pinch of chili flakes. Cook 2-3 minutes per side until pink and curled.","Squeeze lemon juice over the shrimp.","Toast whole wheat bread slices.","Serve shrimp over a bed of spinach with bread on the side."]},
"Aji de Gallina":{prepTime:"15 mins",cookTime:"30 mins",steps:["Poach the chicken breast in lightly salted water for 20-25 minutes at a bare simmer. Remove, cool, and hand-shred into fine threads. Keep the broth.","Boil the potato until tender and slice thick. Hard-boil the egg. Cook the white rice according to package directions.","Soak the bread in a little of the hot broth until completely soft, then blend smooth.","Sweat the finely chopped red onion in olive oil until translucent, add garlic and cook 1 minute more.","Add the aji amarillo paste and fry it hard until the oil separates and the color deepens - this cooks out the raw chili taste and is the step most often skipped.","Stir in the blended bread and cook until it thickens and pulls from the pan. Add the shredded chicken and evaporated milk and simmer gently, without boiling. Take off the heat and stir in the grated parmesan.","Lay the potato slices down, spoon the sauce over them, and serve with rice alongside, garnished with the hard-boiled egg and black olives."]},
"Causa Limena":{prepTime:"30 mins",cookTime:"25 mins",steps:["Boil the potatoes whole and unpeeled in salted water until tender. Peel them while still hot and pass through a ricer immediately - never add water.","Let the puree cool to room temperature, then knead in the aji amarillo paste, lime juice, olive oil and salt until the mass is smooth, elastic and evenly yellow. It should taste distinctly limey and gently spicy.","Poach the chicken breast until cooked through, cool, and shred finely. Bind it with the mayonnaise, a squeeze of lime, salt and pepper.","Hard-boil the egg. Slice the avocado.","Oil a ring mold or small loaf pan. Press in half the potato masa firmly and flat, layer on the avocado, then the chicken filling.","Press the remaining masa over the top, level it, and refrigerate at least 30 minutes so it sets and holds its shape.","Unmold onto the lettuce, garnish with the hard-boiled egg and black olives, and serve cold."]},
"Tallarines Verdes con Bistec":{prepTime:"15 mins",cookTime:"20 mins",steps:["Bring a large pot of well-salted water to the boil for the pasta.","Saute the finely chopped red onion in olive oil until soft and translucent, then add the garlic and cook until fragrant.","Add the spinach and basil and cook just until wilted and the moisture has cooked off, 2-3 minutes. Season with salt and pepper.","Blend the pan contents with the evaporated milk, queso fresco and parmesan until completely smooth and thick. Season at the end - queso fresco varies a lot in saltiness.","Cook the pasta al dente and reserve a cup of the cooking water.","Season the beef sirloin and sear it hard in a hot pan to your liking, then rest it and slice.","Return the green sauce to low heat, add the drained pasta and toss 2 minutes so it coats and clings, loosening with pasta water as needed. Plate the pasta, lay the steak over it, and finish with black pepper."]},
"Ropa Vieja":{prepTime:"40 mins",cookTime:"3 hrs 30 mins",steps:["Cook white rice according to package directions.","Marinate beef sirloin with oregano, cumin, black pepper, mashed garlic, adobo, soy sauce, and juice of half a lemon for at least 30 minutes.","Heat olive oil in a large pot. Sear marinated beef for 3 minutes per side.","Add water and bay leaves to the pot. Cover and braise on low heat for 3 hours.","Remove bay leaves. Shred beef with two forks in the sauce.","Add diced onion, bell pepper, eggplant, and tomato sauce. Cook for 10-15 minutes until vegetables are tender. Serve over rice."]},
"Picanha with Farofa":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook white rice and black beans separately according to package directions.","Season beef sirloin generously with coarse salt.","Grill or pan-sear beef for 4-5 minutes per side for medium-rare.","Dice onion and saute with garlic in a dry pan for farofa flavor base.","Fry an egg sunny-side up.","Slice the steak against the grain. Serve with rice, beans, egg, and a squeeze of lime."]},
"Tortilla Espanola":{prepTime:"10 mins",cookTime:"20 mins",steps:["Peel and thinly slice potato. Slice onion into thin rings.","Heat olive oil in a non-stick skillet. Gently fry potato and onion for 10 minutes until soft.","Beat eggs in a large bowl. Add the cooked potato and onion mixture. Stir in spinach.","Pour the mixture back into the oiled skillet over medium-low heat.","Cook for 6-8 minutes until the bottom is set. Flip using a plate and cook 4 more minutes.","Slide onto a plate and serve warm or at room temperature."]},
"Beef Pho":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook rice noodles according to package directions. Drain and set aside.","Slice beef sirloin very thinly against the grain.","Bring 3 cups water or beef broth to a boil with sliced onion, garlic, sliced ginger, a cinnamon stick, and a splash of soy sauce.","Place noodles in bowls. Arrange raw beef slices on top.","Pour boiling broth over the beef — the heat will cook the thin slices.","Top with spinach, a squeeze of lime, and serve immediately."]},
"Chicken Pho":{prepTime:"10 mins",cookTime:"20 mins",steps:["Slice chicken breast into thin strips.","Bring 3 cups water or chicken broth to a boil with sliced onion, garlic, and a cinnamon stick.","Add chicken strips and simmer for 8-10 minutes until cooked through.","Cook rice noodles according to package directions.","Place noodles in bowls, ladle broth and chicken over them.","Top with spinach and a squeeze of lime."]},
"Bun Tom":{prepTime:"15 mins",cookTime:"10 mins",steps:["Cook rice noodles according to package directions, drain and rinse with cold water.","Season shrimp with salt and pepper. Grill or pan-sear for 2-3 minutes per side.","Julienne cucumber and carrot into thin strips.","Arrange cold noodles in bowls with romaine lettuce.","Top with grilled shrimp, cucumber, and carrot.","Squeeze lime over everything and toss gently."]},
"Tuna Tataki Bowl":{prepTime:"10 mins",cookTime:"10 mins",steps:["Cook white rice according to package directions.","Pat ahi tuna dry and season with salt. Sear in a very hot pan for 30-45 seconds per side.","Slice seared tuna into thin pieces.","Cook edamame in boiling water for 3 minutes. Drain.","Mix a small amount of miso paste with soy sauce for dressing.","Arrange rice in bowl, top with tuna, cucumber, and edamame. Drizzle with dressing."]},
"Chicken Yakitori Bowl":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Cut the chicken into bite-sized pieces.","Mix soy sauce, honey, and sesame oil to make yakitori glaze.","Thread chicken onto skewers or cook in a hot pan, glazing frequently, for 6-8 minutes.","Slice green onion for garnish.","Serve glazed chicken over rice, topped with green onion."]},
"Greek Lemon Chicken":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook brown rice according to package directions.","Season chicken breast with lemon juice, minced garlic, oregano, salt, and pepper.","Heat olive oil in a skillet. Sear chicken for 6-7 minutes per side until cooked through.","Wilt spinach in the same pan for 1-2 minutes.","Slice red onion thinly.","Serve chicken over rice with spinach, red onion, and a lemon wedge."]},
"Seared Tuna Steak":{prepTime:"5 mins",cookTime:"5 mins",steps:["Pat ahi tuna steak dry. Season with salt and pepper.","Heat olive oil in a skillet over very high heat.","Sear tuna for 1-2 minutes per side for rare, 3 minutes for medium.","Mince garlic and squeeze lemon juice.","Arrange spinach and sliced cucumber on a plate.","Place seared tuna on greens. Drizzle with lemon-garlic dressing."]},
"Turkey & Broccoli Bowl":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook brown rice according to package directions.","Slice turkey breast into strips. Mince garlic.","Heat a non-stick pan, cook turkey strips for 4-5 minutes per side until golden.","Steam or blanch broccoli for 3-4 minutes until bright green.","Add a splash of soy sauce to the turkey in the last minute.","Serve turkey and broccoli over rice."]},
"Chicken & Sweet Potato Bowl":{prepTime:"10 mins",cookTime:"25 mins",steps:["Peel and cube sweet potato. Toss with a drizzle of olive oil and roast at 200C for 20 minutes.","Season chicken breast with garlic, salt, and pepper.","Grill or pan-sear chicken for 6-7 minutes per side until cooked through. Slice.","Dice onion and wilt spinach briefly in a hot pan.","Arrange roasted sweet potato, sliced chicken, and spinach in a bowl.","Serve with sauteed onion."]},
"Shrimp Fajitas":{prepTime:"10 mins",cookTime:"10 mins",steps:["Peel and devein shrimp. Season with cumin, paprika, salt, and pepper.","Slice bell pepper and onion into strips. Mince garlic.","Heat a skillet over high heat. Sear shrimp 2-3 minutes per side. Set aside.","In the same pan, cook bell pepper and onion strips for 3-4 minutes. Add minced garlic and cook 30 seconds until fragrant.","Warm tortilla in a dry pan.","Fill tortilla with shrimp, peppers, and onion. Top with cilantro and lime."]},
"Tandoori Chicken":{prepTime:"15 mins",cookTime:"20 mins",steps:["Mix Greek yogurt with minced garlic, lemon juice, and cumin, paprika, turmeric, and garam masala.","Coat the chicken in the marinade. Refrigerate for at least 10 minutes.","Grill or bake chicken at 220C for 15-20 minutes until charred and cooked through.","Cook a small portion of basmati rice.","Slice onion into rings for garnish.","Serve tandoori chicken with rice and onion rings."]},
"Jerk Chicken Rice Bowl":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook white rice according to package directions.","Season the chicken with allspice, thyme, garlic powder, and cayenne.","Grill or pan-sear chicken for 6-7 minutes per side. Let rest, then slice.","Dice bell pepper and onion. Saute briefly.","Heat coconut milk gently for a drizzle.","Serve sliced chicken over rice with peppers, onion, lime, and coconut drizzle."]},
"Pollo a la Plancha":{prepTime:"20 mins",cookTime:"15 mins",steps:["Butterfly or pound the chicken breast to an even thickness so it cooks fast and stays juicy.","Whisk a marinade of olive oil, minced garlic, half the lime juice, cumin, oregano, salt and pepper. Coat the chicken and leave it 15-30 minutes.","Make the salsa criolla: slice the red onion into a very fine julienne, soak it in cold water 10-15 minutes, then drain thoroughly. Toss with aji amarillo paste, the remaining lime juice, chopped cilantro, salt and pepper, and let it rest 10 minutes.","Cook white rice according to package directions.","Get a flat griddle or heavy pan properly hot. Lay the chicken down and leave it undisturbed 4-5 minutes per side until deeply golden and just cooked through.","Rest the chicken 2-3 minutes. Plate with the rice, a simple romaine and tomato salad, and a generous mound of salsa criolla over the chicken."]},
"Turkey Lettuce Wraps":{prepTime:"10 mins",cookTime:"10 mins",steps:["Slice turkey breast into thin strips or small dice.","Heat a non-stick pan over medium-high heat. Cook turkey for 4-5 minutes until golden.","Add a splash of soy sauce and toss to coat in the last minute.","Grate or julienne carrot into thin strips.","Separate romaine lettuce leaves to use as cups.","Fill lettuce cups with turkey and carrot. Squeeze lime over top and serve with sliced onion."]},
"Turkey Kofta Plate":{prepTime:"15 mins",cookTime:"12 mins",steps:["Mince or finely chop turkey breast. Mix with finely diced onion, cumin, coriander, salt, and pepper.","Form into small oval patties or cylinder shapes.","Cook kofta in a hot skillet for 3-4 minutes per side until browned and cooked through.","Warm pita bread in a dry pan.","Slice cucumber and red onion. Mix Greek yogurt with a pinch of garlic for tzatziki.","Serve kofta with pita, hummus, vegetables, and tzatziki."]},
"Turkey Stir Fry with Rice":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Slice turkey breast into thin strips.","Heat sesame oil in a wok over high heat.","Mince garlic and grate ginger, then add to the wok and stir-fry for 30 seconds until fragrant.","Add turkey strips and stir-fry for 3-4 minutes until browned.","Add sliced bell pepper and broccoli florets. Stir-fry for 3 more minutes.","Add soy sauce and toss everything together.","Serve over rice."]},
"Turkey Burrito Bowl":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook brown rice according to package directions.","Season turkey breast strips with cumin, paprika, salt, and pepper.","Cook turkey in a hot pan for 4-5 minutes per side until done. Slice.","Warm black beans in a small pot with a pinch of cumin.","Dice onion and chop cilantro.","Assemble bowl with rice, turkey, black beans, corn, onion, and cilantro. Squeeze lime over top."]},
"Lean Beef Tacos":{prepTime:"10 mins",cookTime:"10 mins",steps:["Season the ground beef with cumin, chili powder, salt, and pepper.","Brown beef in a skillet over medium-high heat for 6-8 minutes, breaking apart.","Warm corn tortillas in a dry pan for 30 seconds per side.","Dice onion and chop cilantro.","Fill tortillas with seasoned beef, onion, and cilantro.","Squeeze lime over tacos and serve."]},
"Five-Spice Duck Stir Fry with Rice":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Slice the duck thinly and toss with five-spice powder, salt, white pepper, and black pepper.","Heat sesame oil in a wok over high heat.","Mince garlic and grate ginger, add to the wok and stir-fry for 30 seconds until fragrant.","Add the duck and stir-fry for 3-4 minutes until just cooked through.","Add sliced bell pepper and broccoli florets, stir-fry for 2-3 minutes.","Splash with soy sauce and toss to coat.","Serve over rice, garnished with sliced green onion."]},
"Peking-Style Duck Wraps":{prepTime:"10 mins",cookTime:"10 mins",steps:["Slice the duck thinly. Mince garlic and grate ginger.","Sear the duck in a hot pan with the garlic and ginger until skin is crispy and meat is cooked through, about 5-6 minutes.","Slice cucumber into thin sticks. Slice green onion lengthwise.","Warm the tortilla in a dry pan for 30 seconds per side.","Smear hoisin sauce on the tortilla. Add the duck, cucumber, and green onion. Roll and serve."]},
"Duck Confit with Lentils":{prepTime:"15 mins",cookTime:"3 hrs",steps:["Season the duck leg generously with salt, pepper, and thyme. Rub into the skin and meat.","Slow-cook the duck leg in its own rendered fat at 90°C / 195°F for 2-3 hours until very tender and falling off the bone.","Dice carrot and onion. Mince garlic.","In a separate pot, sauté carrot, onion, and garlic in a small amount of duck fat until softened.","Add red lentils, a bay leaf, and 2 cups water or stock. Simmer 25-30 minutes until lentils are tender.","Plate the lentils, remove the bay leaf, and arrange the duck leg on top."]},
"Pan-Seared Duck Breast with Cherry Sauce & Brown Rice":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook brown rice according to package directions.","Score the duck breast skin in a crosshatch pattern. Season both sides with salt, pepper, and thyme.","Place the duck breast skin-side down in a cold pan over medium-low heat. Render the fat for about 10 minutes until the skin is crispy and golden.","Flip the duck and cook for 3 more minutes for medium-rare. Rest on a cutting board.","Pour off excess fat. Add minced garlic and finely diced onion (substituting for shallot) to the pan, sauté for 1 minute. Deglaze with cherry sauce and simmer for 2 minutes.","Trim asparagus and steam for 4 minutes until tender-crisp.","Slice the duck thinly. Plate over rice with asparagus alongside, drizzling cherry sauce over the duck."]},
"Duck Confit Tacos":{prepTime:"15 mins",cookTime:"3 hrs",steps:["Season the duck leg with salt, pepper, cumin, and smoked paprika.","Slow-cook the duck leg in its own rendered fat at 90°C / 195°F for 2-3 hours until shreddable.","Shred the duck meat with two forks, discarding any bones.","Warm the corn tortillas in a dry pan for 30 seconds per side.","Fill each tortilla with shredded duck, coleslaw mix, and cilantro. Squeeze lime over the top."]},
"Baked Cod with Lemon & Herbs":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook white rice according to package directions. Steam or blanch broccoli until tender-crisp, about 4 minutes.","Preheat oven to 200\u00b0C (400\u00b0F).","Place cod fillets on a lined baking sheet. Season with salt, pepper, oregano, parsley, and minced garlic.","Drizzle with olive oil and squeeze lemon juice over the fish.","Bake for 12-15 minutes until fish flakes easily with a fork.","Serve cod over rice with broccoli on the side."]}
};

